export const NEWS_PRESETS_BY_ID = new Map(NEWS_PRESETS_LIBRARY.map(p => [p.id, p]));

export const NEWS_PRESETS_BY_CATEGORY = NEWS_PRESET_CATEGORIES.reduce((acc, cat) => {
  acc[cat] = NEWS_PRESETS_LIBRARY.filter(p => p.category === cat);
  return acc;
}, {});

export const NEWS_PRESETS_BY_CLASSIFICATION = ['confirmed', 'macroeconomic', 'speculative', 'rumour', 'correction'].reduce((acc, cls) => {
  acc[cls] = NEWS_PRESETS_LIBRARY.filter(p => p.classification === cls);
  return acc;
}, {});

export const TRAINING_NEWS_PRESETS = NEWS_PRESETS_LIBRARY.filter(p => p.trainingEligibility === true);

export const NEWS_CATEGORIES = NEWS_PRESET_CATEGORIES;
export const PRESETS_BY_CATEGORY = NEWS_PRESETS_BY_CATEGORY;
export const PRESETS_BY_ID = NEWS_PRESETS_BY_ID;

export const RUMOUR_CORRECTION_MAP = new Map(
  NEWS_PRESETS_LIBRARY
    .filter(p => p.correctionRules && p.correctionRules.linkedRumourId)
    .map(p => [p.correctionRules.linkedRumourId, p.id])
);

export function getPresetById(id) {
  if (!id) return null;
  return NEWS_PRESETS_BY_ID.get(id) || NEWS_PRESETS_LIBRARY.find(p => p.id === id || p.step === Number(id));
}

export function getPresetsByCategory(category) {
  if (!category || category === 'All') return NEWS_PRESETS_LIBRARY;
  return NEWS_PRESETS_BY_CATEGORY[category] || NEWS_PRESETS_LIBRARY.filter(p => p.category === category);
}

export function getPresetsByScope(scope) {
  if (!scope || scope === 'All') return NEWS_PRESETS_LIBRARY;
  return NEWS_PRESETS_LIBRARY.filter(p => p.scope.toUpperCase() === scope.toUpperCase());
}

export function getTrainingEligiblePresets() {
  return TRAINING_NEWS_PRESETS;
}

export function getPresetsBySearch(query) {
  if (!query || typeof query !== 'string' || !query.trim()) return NEWS_PRESETS_LIBRARY;
  const q = query.toLowerCase().trim();
  return NEWS_PRESETS_LIBRARY.filter(p => {
    return (
      (p.headline && p.headline.toLowerCase().includes(q)) ||
      (p.shortHeadline && p.shortHeadline.toLowerCase().includes(q)) ||
      (p.description && p.description.toLowerCase().includes(q)) ||
      (p.category && p.category.toLowerCase().includes(q)) ||
      (p.subcategory && p.subcategory.toLowerCase().includes(q)) ||
      (p.country && p.country.toLowerCase().includes(q)) ||
      (p.id && p.id.toLowerCase().includes(q)) ||
      (p.affectedSecurityIds && p.affectedSecurityIds.some(s => s.toLowerCase().includes(q))) ||
      (p.affectedSectors && p.affectedSectors.some(sec => sec.toLowerCase().includes(q)))
    );
  });
}

export function getLinkedCorrection(rumourId) {
  const correctionId = RUMOUR_CORRECTION_MAP.get(rumourId);
  return correctionId ? getPresetById(correctionId) : null;
}

export function validateNewsPreset(preset) {
  const errors = [];
  if (!preset) return { valid: false, errors: ['Preset object required'] };

  if (!preset.headline) {
    errors.push('Headline is required');
  }

  if (!preset.category) {
    errors.push('Category is required');
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

export default NEWS_PRESETS_LIBRARY;
